```isabelle
theory RSF
  imports Complex_Main "HOL-Library.Monad_Syntax" "HOL-Analysis.Analysis" "IEEE_Floating_Point.IEEE" "Refine_Imperative_HOL.IICF"
begin

datatype err = InvalidDimension | InvalidLayerCount | TooLarge | NonFinite | InvalidConfig | ShapeMismatch | DataLengthMismatch | NumericFailure | NotInitialized | BadFileFormat | UnsupportedVersion

datatype 'a result = Ok 'a | Err err

definition bind :: "'a result \<Rightarrow> ('a \<Rightarrow> 'b result) \<Rightarrow> 'b result" where
  "bind m f = (case m of Ok a \<Rightarrow> f a | Err e \<Rightarrow> Err e)"

notation bind (infixr ">>=" 54)

definition return :: "'a \<Rightarrow> 'a result" where
  "return a = Ok a"

definition assert :: "bool \<Rightarrow> err \<Rightarrow> unit result" where
  "assert P e = (if P then Ok () else Err e)"

type_synonym f32 = "(8, 23) float"

definition f32_zero :: "f32" where
  "f32_zero = plus_zero"

definition f32_one :: "f32" where
  "f32_one = IEEE.one"

definition is_finite_f32 :: "f32 \<Rightarrow> bool" where
  "is_finite_f32 x = is_finite x"

definition f32_add :: "f32 \<Rightarrow> f32 \<Rightarrow> f32" where
  "f32_add x y = fadd To_nearest x y"

definition f32_sub :: "f32 \<Rightarrow> f32 \<Rightarrow> f32" where
  "f32_sub x y = fsub To_nearest x y"

definition f32_mul :: "f32 \<Rightarrow> f32 \<Rightarrow> f32" where
  "f32_mul x y = fmul To_nearest x y"

definition f32_div :: "f32 \<Rightarrow> f32 \<Rightarrow> f32" where
  "f32_div x y = fdiv To_nearest x y"

definition f32_exp :: "f32 \<Rightarrow> f32" where
  "f32_exp x = (if is_finite_f32 x then IEEE.float_of (exp (valof x)) else if flt f32_zero x then plus_infinity else f32_zero)"

definition f32_clip :: "f32 \<Rightarrow> f32 \<Rightarrow> f32 \<Rightarrow> f32" where
  "f32_clip x l u = (if fle x l then l else if fle u x then u else x)"

definition f32_eq :: "f32 \<Rightarrow> f32 \<Rightarrow> bool" where
  "f32_eq x y = feq x y"

definition clamp_finite_single :: "f32 \<Rightarrow> f32" where
  "clamp_finite_single x = (if is_finite_f32 x then x else f32_zero)"

record tensor =
  shape :: "nat list"
  data :: "f32 list"

definition tensor_valid :: "tensor \<Rightarrow> bool" where
  "tensor_valid t = (length (shape t) = 2 \<and> (case shape t of [r, c] \<Rightarrow> length (data t) = r * c | _ \<Rightarrow> False))"

definition get_rows :: "tensor \<Rightarrow> nat" where
  "get_rows t = (case shape t of r # _ \<Rightarrow> r | _ \<Rightarrow> 0)"

definition get_cols :: "tensor \<Rightarrow> nat" where
  "get_cols t = (case shape t of _ # c # _ \<Rightarrow> c | _ \<Rightarrow> 0)"

definition get_elem :: "tensor \<Rightarrow> nat \<Rightarrow> nat \<Rightarrow> f32" where
  "get_elem t r c = data t ! (r * get_cols t + c)"

definition set_elem :: "tensor \<Rightarrow> nat \<Rightarrow> nat \<Rightarrow> f32 \<Rightarrow> tensor" where
  "set_elem t r c v = t \<lparr> data := list_update (data t) (r * get_cols t + c) v \<rparr>"

definition assert2DAndLen :: "tensor \<Rightarrow> unit result" where
  "assert2DAndLen t = do {
    assert (length (shape t) = 2) ShapeMismatch;
    let r = get_rows t; let c = get_cols t in
    assert (length (data t) = r * c) DataLengthMismatch;
    return ()
  }"

definition tensor_zeros :: "nat \<Rightarrow> nat \<Rightarrow> tensor" where
  "tensor_zeros r c = \<lparr> shape = [r, c], data = replicate (r * c) f32_zero \<rparr>"

definition tensor_copy :: "tensor \<Rightarrow> tensor result" where
  "tensor_copy t = do {
    assert2DAndLen t;
    return \<lparr> shape = shape t, data = data t \<rparr>
  }"

definition tensor_transpose :: "tensor \<Rightarrow> tensor result" where
  "tensor_transpose t = do {
    assert2DAndLen t;
    let r = get_rows t; let c = get_cols t in
    let new_data = concat (map (\<lambda>j. map (\<lambda>i. get_elem t i j) [0..<r]) [0..<c]) in
    return \<lparr> shape = [c, r], data = new_data \<rparr>
  }"

definition tensor_matmul :: "tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "tensor_matmul a b = do {
    assert2DAndLen a;
    assert2DAndLen b;
    let ar = get_rows a; let ac = get_cols a;
    let br = get_rows b; let bc = get_cols b in
    assert (ac = br) ShapeMismatch;
    let result_data = concat (map (\<lambda>i. map (\<lambda>j. 
      foldl f32_add f32_zero (map (\<lambda>k. f32_mul (get_elem a i k) (get_elem b k j)) [0..<ac])) [0..<bc]) [0..<ar]) in
    return \<lparr> shape = [ar, bc], data = result_data \<rparr>
  }"

definition tensor_add_inplace :: "tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "tensor_add_inplace t1 t2 = do {
    assert2DAndLen t1;
    assert2DAndLen t2;
    assert (shape t1 = shape t2) ShapeMismatch;
    return \<lparr> shape = shape t1, data = map2 f32_add (data t1) (data t2) \<rparr>
  }"

definition tensor_sub_inplace :: "tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "tensor_sub_inplace t1 t2 = do {
    assert2DAndLen t1;
    assert2DAndLen t2;
    assert (shape t1 = shape t2) ShapeMismatch;
    return \<lparr> shape = shape t1, data = map2 f32_sub (data t1) (data t2) \<rparr>
  }"

definition tensor_mul_inplace :: "tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "tensor_mul_inplace t1 t2 = do {
    assert2DAndLen t1;
    assert2DAndLen t2;
    assert (shape t1 = shape t2) ShapeMismatch;
    return \<lparr> shape = shape t1, data = map2 f32_mul (data t1) (data t2) \<rparr>
  }"

definition tensor_div_inplace :: "tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "tensor_div_inplace t1 t2 = do {
    assert2DAndLen t1;
    assert2DAndLen t2;
    assert (shape t1 = shape t2) ShapeMismatch;
    assert (\<forall>x \<in> set (data t2). \<not> f32_eq x f32_zero) NumericFailure;
    return \<lparr> shape = shape t1, data = map2 f32_div (data t1) (data t2) \<rparr>
  }"

definition tensor_clip :: "tensor \<Rightarrow> f32 \<Rightarrow> f32 \<Rightarrow> tensor result" where
  "tensor_clip t l u = do {
    assert2DAndLen t;
    return \<lparr> shape = shape t, data = map (\<lambda>x. f32_clip x l u) (data t) \<rparr>
  }"

definition tensor_exp :: "tensor \<Rightarrow> tensor result" where
  "tensor_exp t = do {
    assert2DAndLen t;
    return \<lparr> shape = shape t, data = map f32_exp (data t) \<rparr>
  }"

definition clamp_finite_inplace :: "tensor \<Rightarrow> tensor" where
  "clamp_finite_inplace t = t \<lparr> data := map clamp_finite_single (data t) \<rparr>"

definition tensor_add_bias_rows :: "tensor \<Rightarrow> f32 list \<Rightarrow> tensor result" where
  "tensor_add_bias_rows t bias = do {
    assert2DAndLen t;
    let r = get_rows t; let c = get_cols t in
    assert (length bias = c) DataLengthMismatch;
    let new_data = concat (map (\<lambda>i. map (\<lambda>j. f32_add (get_elem t i j) (bias ! j)) [0..<c]) [0..<r]) in
    return \<lparr> shape = [r, c], data = new_data \<rparr>
  }"

definition check_no_zero :: "tensor \<Rightarrow> bool" where
  "check_no_zero t = (\<forall>x \<in> set (data t). \<not> f32_eq x f32_zero \<and> is_finite_f32 x)"

record rsf_layer_config =
  clip_min :: f32
  clip_max :: f32
  seed_offset :: nat
  grad_mean :: bool

record rsf_layer =
  s_weight :: tensor
  t_weight :: tensor
  s_bias :: "f32 list"
  t_bias :: "f32 list"
  s_weight_grad :: tensor
  t_weight_grad :: tensor
  s_bias_grad :: "f32 list"
  t_bias_grad :: "f32 list"
  dim :: nat
  clip_min :: f32
  clip_max :: f32
  grad_mean :: bool

definition rsf_layer_valid :: "rsf_layer \<Rightarrow> bool" where
  "rsf_layer_valid L = (
    dim L > 0 \<and>
    tensor_valid (s_weight L) \<and> shape (s_weight L) = [dim L, dim L] \<and>
    tensor_valid (t_weight L) \<and> shape (t_weight L) = [dim L, dim L] \<and>
    length (s_bias L) = dim L \<and>
    length (t_bias L) = dim L \<and>
    tensor_valid (s_weight_grad L) \<and> shape (s_weight_grad L) = [dim L, dim L] \<and>
    tensor_valid (t_weight_grad L) \<and> shape (t_weight_grad L) = [dim L, dim L] \<and>
    length (s_bias_grad L) = dim L \<and>
    length (t_bias_grad L) = dim L \<and>
    is_finite_f32 (clip_min L) \<and> is_finite_f32 (clip_max L) \<and>
    flt (clip_min L) (clip_max L)
  )"

definition rsf_layer_init :: "nat \<Rightarrow> rsf_layer_config \<Rightarrow> rsf_layer result" where
  "rsf_layer_init d cfg = do {
    assert (d > 0) InvalidDimension;
    assert (d \<le> 10000) TooLarge;
    assert (is_finite_f32 (clip_min cfg) \<and> is_finite_f32 (clip_max cfg)) NonFinite;
    assert (flt (clip_min cfg) (clip_max cfg)) InvalidConfig;
    return \<lparr>
      s_weight = tensor_zeros d d,
      t_weight = tensor_zeros d d,
      s_bias = replicate d f32_zero,
      t_bias = replicate d f32_zero,
      s_weight_grad = tensor_zeros d d,
      t_weight_grad = tensor_zeros d d,
      s_bias_grad = replicate d f32_zero,
      t_bias_grad = replicate d f32_zero,
      dim = d,
      clip_min = clip_min cfg,
      clip_max = clip_max cfg,
      grad_mean = grad_mean cfg
    \<rparr>
  }"

definition rsf_layer_zero_gradients :: "rsf_layer \<Rightarrow> rsf_layer" where
  "rsf_layer_zero_gradients L = L \<lparr>
    s_weight_grad := tensor_zeros (dim L) (dim L),
    t_weight_grad := tensor_zeros (dim L) (dim L),
    s_bias_grad := replicate (dim L) f32_zero,
    t_bias_grad := replicate (dim L) f32_zero
  \<rparr>"

definition assertPair :: "rsf_layer \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> nat result" where
  "assertPair L a b = do {
    assert2DAndLen a;
    assert2DAndLen b;
    let ar = get_rows a; let ac = get_cols a;
    let br = get_rows b; let bc = get_cols b in
    assert (ac = dim L \<and> bc = dim L) ShapeMismatch;
    assert (ar = br) ShapeMismatch;
    assert (length (s_bias L) = dim L \<and> length (t_bias L) = dim L) ShapeMismatch;
    assert (is_finite_f32 (clip_min L) \<and> is_finite_f32 (clip_max L)) NonFinite;
    assert (flt (clip_min L) (clip_max L)) InvalidConfig;
    return ar
  }"

definition rsf_layer_forward :: "rsf_layer \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> (tensor \<times> tensor) result" where
  "rsf_layer_forward L x1 x2 = do {
    batch_size \<leftarrow> assertPair L x1 x2;
    x2_t \<leftarrow> tensor_transpose x2;
    s_x2_t \<leftarrow> tensor_matmul (s_weight L) x2_t;
    s_x2 \<leftarrow> tensor_transpose s_x2_t;
    s_x2 \<leftarrow> tensor_add_bias_rows s_x2 (s_bias L);
    let s_x2 = clamp_finite_inplace s_x2 in
    s_x2 \<leftarrow> tensor_clip s_x2 (clip_min L) (clip_max L);
    let s_x2 = clamp_finite_inplace s_x2 in
    s_x2 \<leftarrow> tensor_exp s_x2;
    let s_x2 = clamp_finite_inplace s_x2 in
    y1 \<leftarrow> tensor_mul_inplace x1 s_x2;
    y1_t \<leftarrow> tensor_transpose y1;
    t_y1_t \<leftarrow> tensor_matmul (t_weight L) y1_t;
    t_y1 \<leftarrow> tensor_transpose t_y1_t;
    t_y1 \<leftarrow> tensor_add_bias_rows t_y1 (t_bias L);
    let t_y1 = clamp_finite_inplace t_y1 in
    y2 \<leftarrow> tensor_add_inplace x2 t_y1;
    let y2 = clamp_finite_inplace y2 in
    return (y1, y2)
  }"

definition rsf_layer_inverse :: "rsf_layer \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> (tensor \<times> tensor) result" where
  "rsf_layer_inverse L y1 y2 = do {
    batch_size \<leftarrow> assertPair L y1 y2;
    y1_t \<leftarrow> tensor_transpose y1;
    t_y1_t \<leftarrow> tensor_matmul (t_weight L) y1_t;
    t_y1 \<leftarrow> tensor_transpose t_y1_t;
    t_y1 \<leftarrow> tensor_add_bias_rows t_y1 (t_bias L);
    let t_y1 = clamp_finite_inplace t_y1 in
    x2 \<leftarrow> tensor_sub_inplace y2 t_y1;
    let x2 = clamp_finite_inplace x2 in
    x2_t \<leftarrow> tensor_transpose x2;
    s_x2_t \<leftarrow> tensor_matmul (s_weight L) x2_t;
    s_x2 \<leftarrow> tensor_transpose s_x2_t;
    s_x2 \<leftarrow> tensor_add_bias_rows s_x2 (s_bias L);
    let s_x2 = clamp_finite_inplace s_x2 in
    s_x2 \<leftarrow> tensor_clip s_x2 (clip_min L) (clip_max L);
    let s_x2 = clamp_finite_inplace s_x2 in
    s_x2 \<leftarrow> tensor_exp s_x2;
    let s_x2 = clamp_finite_inplace s_x2 in
    assert (check_no_zero s_x2) NumericFailure;
    x1 \<leftarrow> tensor_div_inplace y1 s_x2;
    let x1 = clamp_finite_inplace x1 in
    return (x1, x2)
  }"

definition outer_product :: "tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "outer_product v1 v2 = do {
    assert2DAndLen v1;
    assert2DAndLen v2;
    let b1 = get_rows v1; let d1 = get_cols v1;
    let b2 = get_rows v2; let d2 = get_cols v2 in
    assert (b1 = b2 \<and> d1 = d2) ShapeMismatch;
    let accum_data = replicate (d1 * d1) f32_zero in
    let result_data = foldl (\<lambda>acc i.
      foldl (\<lambda>acc2 j.
        foldl (\<lambda>acc3 k.
          list_update acc3 (j * d1 + k) 
            (f32_add (acc3 ! (j * d1 + k))
                     (f32_mul (get_elem v1 i j) (get_elem v2 i k))))
        acc2 [0..<d1])
      acc [0..<d1])
    accum_data [0..<b1] in
    return \<lparr> shape = [d1, d1], data = result_data \<rparr>
  }"

definition rsf_layer_backward :: "rsf_layer \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> (tensor \<times> tensor \<times> rsf_layer) result" where
  "rsf_layer_backward L y1 y2 dy1 dy2 = do {
    batch_size \<leftarrow> assertPair L y1 y2;
    _ \<leftarrow> assertPair L dy1 dy2;

    y1_t \<leftarrow> tensor_transpose y1;
    t_y1_t \<leftarrow> tensor_matmul (t_weight L) y1_t;
    t_y1 \<leftarrow> tensor_transpose t_y1_t;
    t_y1 \<leftarrow> tensor_add_bias_rows t_y1 (t_bias L);
    let t_y1 = clamp_finite_inplace t_y1 in
    x2 \<leftarrow> tensor_copy y2;
    x2 \<leftarrow> tensor_sub_inplace x2 t_y1;
    let x2 = clamp_finite_inplace x2 in

    dy2_copy \<leftarrow> tensor_copy dy2;
    dy2_t \<leftarrow> tensor_transpose dy2_copy;
    dt \<leftarrow> tensor_matmul dy2_t y1;

    let grad_scale = if grad_mean L then f32_div f32_one (IEEE.float_of (real batch_size)) else f32_one in
    let t_weight_grad_new = \<lparr> shape = shape (t_weight_grad L), 
                                 data = map2 (\<lambda>g d. f32_add g (f32_mul d grad_scale)) 
                                             (data (t_weight_grad L)) (data dt) \<rparr> in

    let t_bias_grad_new = map (\<lambda>d. 
      f32_add (s_bias_grad L ! d) 
              (f32_mul grad_scale 
                      (foldl f32_add f32_zero 
                            (map (\<lambda>b. get_elem dy2_copy b d) [0..<batch_size])))) 
      [0..<dim L] in

    t_weight_t \<leftarrow> tensor_transpose (t_weight L);
    grad_from_t_t \<leftarrow> tensor_matmul t_weight_t dy2_t;
    grad_from_t \<leftarrow> tensor_transpose grad_from_t_t;

    dy1_updated \<leftarrow> tensor_copy dy1;
    dy1_updated \<leftarrow> tensor_add_inplace dy1_updated grad_from_t;
    let dy1_updated = clamp_finite_inplace dy1_updated in

    x2_t \<leftarrow> tensor_transpose x2;
    s_pre_t \<leftarrow> tensor_matmul (s_weight L) x2_t;
    s_pre \<leftarrow> tensor_transpose s_pre_t;
    s_pre \<leftarrow> tensor_add_bias_rows s_pre (s_bias L);
    let s_pre = clamp_finite_inplace s_pre in

    s_clipped \<leftarrow> tensor_copy s_pre;
    s_clipped \<leftarrow> tensor_clip s_clipped (clip_min L) (clip_max L);
    let s_clipped = clamp_finite_inplace s_clipped in
    exp_s \<leftarrow> tensor_copy s_clipped;
    exp_s \<leftarrow> tensor_exp exp_s;
    let exp_s = clamp_finite_inplace exp_s in

    assert (check_no_zero exp_s) NumericFailure;

    x1 \<leftarrow> tensor_copy y1;
    x1 \<leftarrow> tensor_div_inplace x1 exp_s;
    let x1 = clamp_finite_inplace x1 in

    dx1 \<leftarrow> tensor_mul_inplace dy1_updated exp_s;

    dscale \<leftarrow> tensor_copy dy1_updated;
    dscale \<leftarrow> tensor_mul_inplace dscale x1;
    ds \<leftarrow> tensor_copy dscale;
    ds \<leftarrow> tensor_mul_inplace ds exp_s;

    let ds_zeroed = \<lparr> shape = shape ds,
                        data = map (\<lambda>i. 
                                let b = i div dim L; let d = i mod dim L;
                                let v = get_elem s_pre b d in
                                if \<not> is_finite_f32 v \<or> flt v (clip_min L) \<or> flt (clip_max L) v
                                then f32_zero else (data ds) ! i)
                              [0..<length (data ds)] \<rparr> in

    ds_t \<leftarrow> tensor_transpose ds_zeroed;
    ds_w \<leftarrow> tensor_matmul ds_t x2;

    let s_weight_grad_new = \<lparr> shape = shape (s_weight_grad L),
                                 data = map2 (\<lambda>g d. f32_add g (f32_mul d grad_scale))
                                             (data (s_weight_grad L)) (data ds_w) \<rparr> in

    let s_bias_grad_new = map (\<lambda>d.
      f32_add (s_bias_grad L ! d)
              (f32_mul grad_scale
                      (foldl f32_add f32_zero
                            (map (\<lambda>b. get_elem ds_zeroed b d) [0..<batch_size]))))
      [0..<dim L] in

    s_weight_t \<leftarrow> tensor_transpose (s_weight L);
    grad_from_s_t \<leftarrow> tensor_matmul s_weight_t ds_t;
    grad_from_s \<leftarrow> tensor_transpose grad_from_s_t;

    dx2 \<leftarrow> tensor_add_inplace dy2_copy grad_from_s;
    let dx1 = clamp_finite_inplace dx1 in
    let dx2 = clamp_finite_inplace dx2 in

    let L_updated = L \<lparr> s_weight_grad := s_weight_grad_new,
                         t_weight_grad := t_weight_grad_new,
                         s_bias_grad := s_bias_grad_new,
                         t_bias_grad := t_bias_grad_new \<rparr> in

    return (dx1, dx2, L_updated)
  }"

record rsf_config =
  clip_min :: f32
  clip_max :: f32
  grad_mean :: bool
  max_dim :: nat
  max_layers :: nat

record rsf =
  rsf_dim :: nat
  rsf_num_layers :: nat
  rsf_layers :: "rsf_layer list"
  rsf_config :: rsf_config
  rsf_freed :: bool

definition rsf_valid :: "rsf \<Rightarrow> bool" where
  "rsf_valid R = (
    rsf_dim R > 0 \<and>
    rsf_num_layers R > 0 \<and>
    length (rsf_layers R) = rsf_num_layers R \<and>
    (\<forall>L \<in> set (rsf_layers R). rsf_layer_valid L \<and> dim L = rsf_dim R) \<and>
    is_finite_f32 (clip_min (rsf_config R)) \<and>
    is_finite_f32 (clip_max (rsf_config R)) \<and>
    flt (clip_min (rsf_config R)) (clip_max (rsf_config R))
  )"

definition rsf_init :: "nat \<Rightarrow> nat \<Rightarrow> rsf_config \<Rightarrow> rsf result" where
  "rsf_init d num_layers cfg = do {
    assert (d > 0) InvalidDimension;
    assert (num_layers > 0) InvalidLayerCount;
    assert (d \<le> max_dim cfg \<and> num_layers \<le> max_layers cfg) TooLarge;
    assert (is_finite_f32 (clip_min cfg) \<and> is_finite_f32 (clip_max cfg)) NonFinite;
    assert (flt (clip_min cfg) (clip_max cfg)) InvalidConfig;

    let layer_cfg = \<lparr> clip_min = clip_min cfg, clip_max = clip_max cfg, 
                       seed_offset = 0, grad_mean = grad_mean cfg \<rparr> in

    layers_result \<leftarrow> foldl (\<lambda>acc_r i.
      acc_r >>= (\<lambda>acc.
        let cfg_i = layer_cfg \<lparr> seed_offset := i * 1000 \<rparr> in
        rsf_layer_init d cfg_i >>= (\<lambda>layer.
          return (layer # acc))))
      (return []) [0..<num_layers];

    let layers = rev layers_result in

    return \<lparr> rsf_dim = d, rsf_num_layers = num_layers, rsf_layers = layers,
             rsf_config = cfg, rsf_freed = False \<rparr>
  }"

definition rsf_deinit :: "rsf \<Rightarrow> rsf" where
  "rsf_deinit R = R \<lparr> rsf_freed := True \<rparr>"

definition split :: "rsf \<Rightarrow> tensor \<Rightarrow> (tensor \<times> tensor) result" where
  "split R x = do {
    assert2DAndLen x;
    let b = get_rows x; let total_dim = get_cols x in
    assert (total_dim = 2 * rsf_dim R) ShapeMismatch;

    let x1_data = concat (map (\<lambda>i. map (\<lambda>d. get_elem x i d) [0..<rsf_dim R]) [0..<b]) in
    let x2_data = concat (map (\<lambda>i. map (\<lambda>d. get_elem x i (rsf_dim R + d)) [0..<rsf_dim R]) [0..<b]) in

    return (\<lparr> shape = [b, rsf_dim R], data = x1_data \<rparr>,
            \<lparr> shape = [b, rsf_dim R], data = x2_data \<rparr>)
  }"

definition merge :: "rsf \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "merge R x1 x2 = do {
    assert2DAndLen x1;
    assert2DAndLen x2;
    let b1 = get_rows x1; let d1 = get_cols x1;
    let b2 = get_rows x2; let d2 = get_cols x2 in
    assert (b1 = b2 \<and> d1 = rsf_dim R \<and> d2 = rsf_dim R) ShapeMismatch;

    let merged_data = concat (map (\<lambda>i.
      (map (\<lambda>d. get_elem x1 i d) [0..<rsf_dim R]) @
      (map (\<lambda>d. get_elem x2 i d) [0..<rsf_dim R]))
      [0..<b1]) in

    return \<lparr> shape = [b1, 2 * rsf_dim R], data = merged_data \<rparr>
  }"

definition rsf_zero_gradients :: "rsf \<Rightarrow> rsf" where
  "rsf_zero_gradients R = R \<lparr> rsf_layers := map rsf_layer_zero_gradients (rsf_layers R) \<rparr>"

definition rsf_forward :: "rsf \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "rsf_forward R x = do {
    assert (\<not> rsf_freed R) NotInitialized;
    (x1, x2) \<leftarrow> split R x;
    (y1, y2) \<leftarrow> foldl (\<lambda>acc_r L.
      acc_r >>= (\<lambda>(a1, a2). rsf_layer_forward L a1 a2))
      (return (x1, x2)) (rsf_layers R);
    merge R y1 y2
  }"

definition rsf_inverse :: "rsf \<Rightarrow> tensor \<Rightarrow> tensor result" where
  "rsf_inverse R y = do {
    assert (\<not> rsf_freed R) NotInitialized;
    (y1, y2) \<leftarrow> split R y;
    (x1, x2) \<leftarrow> foldl (\<lambda>acc_r L.
      acc_r >>= (\<lambda>(a1, a2). rsf_layer_inverse L a1 a2))
      (return (y1, y2)) (rev (rsf_layers R));
    merge R x1 x2
  }"

definition rsf_backward :: "rsf \<Rightarrow> tensor \<Rightarrow> tensor \<Rightarrow> (tensor \<times> rsf) result" where
  "rsf_backward R input grad_output = do {
    assert (\<not> rsf_freed R) NotInitialized;
    assert2DAndLen input;
    assert2DAndLen grad_output;
    assert (shape input = shape grad_output) ShapeMismatch;
    assert (get_cols input = 2 * rsf_dim R) ShapeMismatch;

    x \<leftarrow> tensor_copy input;
    x \<leftarrow> rsf_forward R x;
    (y1, y2) \<leftarrow> split R x;
    (dy1, dy2) \<leftarrow> split R grad_output;

    (dx1, dx2, layers_updated, _) \<leftarrow> foldl (\<lambda>acc_r idx.
      acc_r >>= (\<lambda>(cur_dy1, cur_dy2, layers_acc, cur_y1_y2_opt).
        case cur_y1_y2_opt of Some (cur_y1, cur_y2) \<Rightarrow>
          let L = rsf_layers R ! (idx - 1) in
          rsf_layer_backward L cur_y1 cur_y2 cur_dy1 cur_dy2 >>= (\<lambda>(dx1_new, dx2_new, L_updated).
            return (dx1_new, dx2_new, L_updated # layers_acc, None)) |
        None \<Rightarrow> Err NumericFailure))
      (return (dy1, dy2, [], Some (y1, y2)))
      (rev [1..<rsf_num_layers R + 1]);

    grad_input \<leftarrow> merge R dx1 dx2;
    return (grad_input, R \<lparr> rsf_layers := rev layers_updated \<rparr>)
  }"

type_synonym byte = "8 word"

definition to_le_u32 :: "32 word \<Rightarrow> byte list" where
  "to_le_u32 w = map (\<lambda>i. ucast ((w >> (8 * i)) AND 0xFF)) [0..<4]"

definition to_le_u64 :: "64 word \<Rightarrow> byte list" where
  "to_le_u64 w = map (\<lambda>i. ucast ((w >> (8 * i)) AND 0xFF)) [0..<8]"

definition from_le_u32 :: "byte list \<Rightarrow> 32 word option" where
  "from_le_u32 bs = (if length bs = 4 then Some (foldl (\<lambda>acc (i, b). acc OR ((ucast b) << (8 * i))) 0 (zip [0..<4] bs)) else None)"

definition from_le_u64 :: "byte list \<Rightarrow> 64 word option" where
  "from_le_u64 bs = (if length bs = 8 then Some (foldl (\<lambda>acc (i, b). acc OR ((ucast b) << (8 * i))) 0 (zip [0..<8] bs)) else None)"

definition float_to_bits :: "f32 \<Rightarrow> 32 word" where
  "float_to_bits f = word_of_int (THE i. float_of_int i = f)"

definition bits_to_float :: "32 word \<Rightarrow> f32" where
  "bits_to_float w = float_of_int (uint w)"

definition save_f32_list :: "f32 list \<Rightarrow> byte list" where
  "save_f32_list fs = concat (map (to_le_u32 \<circ> float_to_bits) fs)"

definition rsf_save :: "rsf \<Rightarrow> byte list result" where
  "rsf_save R = do {
    assert (\<not> rsf_freed R) NotInitialized;
    assert (rsf_valid R) InvalidConfig;

    let magic = [82, 83, 70, 48] in
    let version = to_le_u32 1 in
    let num_layers_bytes = to_le_u64 (rsf_num_layers R) in
    let dim_bytes = to_le_u64 (rsf_dim R) in
    let cfg = rsf_config R in
    let clip_min_bytes = to_le_u32 (float_to_bits (clip_min cfg)) in
    let clip_max_bytes = to_le_u32 (float_to_bits (clip_max cfg)) in
    let grad_mean_byte = [if grad_mean cfg then 1 else 0] in

    let header = magic @ version @ num_layers_bytes @ dim_bytes @ 
                 clip_min_bytes @ clip_max_bytes @ grad_mean_byte in

    let layer_data = concat (map (\<lambda>L.
      let layer_clip_min_bytes = to_le_u32 (float_to_bits (clip_min L)) in
      let layer_clip_max_bytes = to_le_u32 (float_to_bits (clip_max L)) in
      let layer_grad_mean_byte = [if grad_mean L then 1 else 0] in
      let s_w = save_f32_list (data (s_weight L)) in
      let t_w = save_f32_list (data (t_weight L)) in
      let s_b = save_f32_list (s_bias L) in
      let t_b = save_f32_list (t_bias L) in
      layer_clip_min_bytes @ layer_clip_max_bytes @ layer_grad_mean_byte @ s_w @ t_w @ s_b @ t_b)
      (rsf_layers R)) in

    return (header @ layer_data)
  }"

definition rsf_load :: "byte list \<Rightarrow> rsf result" where
  "rsf_load bytes = do {
    assert (length bytes \<ge> 37) BadFileFormat;

    let magic = take 4 bytes in
    assert (magic = [82, 83, 70, 48]) BadFileFormat;

    version \<leftarrow> (case from_le_u32 (take 4 (drop 4 bytes)) of Some v \<Rightarrow> Ok v | None \<Rightarrow> Err BadFileFormat);
    assert (version = 1) UnsupportedVersion;

    num_layers_word \<leftarrow> (case from_le_u64 (take 8 (drop 8 bytes)) of Some n \<Rightarrow> Ok n | None \<Rightarrow> Err BadFileFormat);
    dim_word \<leftarrow> (case from_le_u64 (take 8 (drop 16 bytes)) of Some d \<Rightarrow> Ok d | None \<Rightarrow> Err BadFileFormat);

    let num_layers = unat num_layers_word in
    let d = unat dim_word in

    assert (num_layers > 0 \<and> d > 0) InvalidDimension;
    assert (num_layers \<le> 1048576 \<and> d \<le> 1048576) TooLarge;

    clip_min_word \<leftarrow> (case from_le_u32 (take 4 (drop 24 bytes)) of Some w \<Rightarrow> Ok w | None \<Rightarrow> Err BadFileFormat);
    clip_max_word \<leftarrow> (case from_le_u32 (take 4 (drop 28 bytes)) of Some w \<Rightarrow> Ok w | None \<Rightarrow> Err BadFileFormat);

    let cmin = bits_to_float clip_min_word in
    let cmax = bits_to_float clip_max_word in
    let gmean = (bytes ! 32 = 1) in

    assert (is_finite_f32 cmin \<and> is_finite_f32 cmax \<and> flt cmin cmax) InvalidConfig;

    let cfg = \<lparr> clip_min = cmin, clip_max = cmax, grad_mean = gmean, 
                 max_dim = 1048576, max_layers = 1048576 \<rparr> in

    rsf_init d num_layers cfg
  }"

lemma bind_return_left: "bind (return x) f = f x"
  unfolding bind_def return_def by simp

lemma bind_return_right: "bind m return = m"
  unfolding bind_def return_def by (cases m) auto

lemma bind_assoc: "bind (bind m f) g = bind m (\<lambda>x. bind (f x) g)"
  unfolding bind_def by (cases m) auto

lemma bind_error: "bind (Err e) f = Err e"
  unfolding bind_def by simp

lemma assert_true: "assert True e = Ok ()"
  unfolding assert_def by simp

lemma assert_false: "assert False e = Err e"
  unfolding assert_def by simp

lemma tensor_valid_zeros: "tensor_valid (tensor_zeros r c)"
  unfolding tensor_valid_def tensor_zeros_def get_rows_def get_cols_def by simp

lemma shape_len: "tensor_valid t \<Longrightarrow> length (shape t) = 2"
  unfolding tensor_valid_def by auto

lemma data_len: "tensor_valid t \<Longrightarrow> length (data t) = get_rows t * get_cols t"
  unfolding tensor_valid_def get_rows_def get_cols_def by (auto split: list.splits)

lemma row_major_index: "\<lbrakk>tensor_valid t; i < get_rows t; j < get_cols t\<rbrakk> \<Longrightarrow> i * get_cols t + j < length (data t)"
  using data_len by auto

lemma f32_mul_comm: "f32_mul x y = f32_mul y x"
  unfolding f32_mul_def by (simp add: fmul_commute)

lemma clamp_finite_is_finite: "is_finite_f32 (clamp_finite_single x)"
  unfolding clamp_finite_single_def is_finite_f32_def f32_zero_def by auto

lemma split_merge_inverse: "\<lbrakk>rsf_valid R; tensor_valid t; shape t = [b, 2 * rsf_dim R]; split R t = Ok (x1, x2); merge R x1 x2 = Ok t'\<rbrakk> \<Longrightarrow> t' = t"
  unfolding split_def merge_def bind_def assert_def assert2DAndLen_def return_def Let_def get_rows_def get_cols_def tensor_valid_def get_elem_def
  by (auto simp: nth_equalityI split: list.splits if_splits result.splits)

lemma split_preserves_batch: "\<lbrakk>rsf_valid R; tensor_valid t; shape t = [b, 2 * rsf_dim R]; split R t = Ok (x1, x2)\<rbrakk> \<Longrightarrow> get_rows x1 = b \<and> get_cols x1 = rsf_dim R \<and> get_rows x2 = b \<and> get_cols x2 = rsf_dim R"
  unfolding split_def bind_def assert_def assert2DAndLen_def return_def Let_def get_rows_def get_cols_def
  by (auto split: list.splits if_splits result.splits)

lemma merge_dimensions: "\<lbrakk>rsf_valid R; tensor_valid x1; tensor_valid x2; get_rows x1 = b; get_cols x1 = rsf_dim R; get_rows x2 = b; get_cols x2 = rsf_dim R; merge R x1 x2 = Ok t\<rbrakk> \<Longrightarrow> shape t = [b, 2 * rsf_dim R]"
  unfolding merge_def bind_def assert_def assert2DAndLen_def return_def Let_def get_rows_def get_cols_def tensor_valid_def
  by (auto split: list.splits if_splits result.splits)

lemma rsf_init_valid: "\<lbrakk>d > 0; num_layers > 0; d \<le> max_dim cfg; num_layers \<le> max_layers cfg; is_finite_f32 (clip_min cfg); is_finite_f32 (clip_max cfg); flt (clip_min cfg) (clip_max cfg); rsf_init d num_layers cfg = Ok R\<rbrakk> \<Longrightarrow> rsf_valid R \<and> \<not> rsf_freed R"
  unfolding rsf_init_def rsf_valid_def bind_def assert_def return_def rsf_layer_init_def
  by (auto split: if_splits result.splits)

lemma rsf_deinit_idempotent: "rsf_deinit (rsf_deinit R) = rsf_deinit R"
  unfolding rsf_deinit_def by auto

lemma rsf_freed_prevents_forward: "rsf_freed R \<Longrightarrow> rsf_forward R x = Err NotInitialized"
  unfolding rsf_forward_def bind_def assert_def by simp

lemma rsf_freed_prevents_inverse: "rsf_freed R \<Longrightarrow> rsf_inverse R y = Err NotInitialized"
  unfolding rsf_inverse_def bind_def assert_def by simp

lemma rsf_freed_prevents_backward: "rsf_freed R \<Longrightarrow> rsf_backward R input grad = Err NotInitialized"
  unfolding rsf_backward_def bind_def assert_def by simp

lemma rsf_save_magic: "\<lbrakk>rsf_valid R; \<not> rsf_freed R; rsf_save R = Ok bytes\<rbrakk> \<Longrightarrow> take 4 bytes = [82, 83, 70, 48]"
  unfolding rsf_save_def bind_def assert_def Let_def return_def by (auto split: if_splits result.splits)

lemma rsf_layer_forward_shape: "\<lbrakk>rsf_layer_valid L; tensor_valid x1; tensor_valid x2; get_cols x1 = dim L; get_cols x2 = dim L; get_rows x1 = b; get_rows x2 = b; rsf_layer_forward L x1 x2 = Ok (y1, y2)\<rbrakk> \<Longrightarrow> get_rows y1 = b \<and> get_cols y1 = dim L \<and> get_rows y2 = b \<and> get_cols y2 = dim L"
  unfolding rsf_layer_forward_def bind_def assertPair_def assert2DAndLen_def assert_def return_def Let_def rsf_layer_valid_def
  by (auto split: if_splits result.splits list.splits)

lemma rsf_layer_inverse_shape: "\<lbrakk>rsf_layer_valid L; tensor_valid y1; tensor_valid y2; get_cols y1 = dim L; get_cols y2 = dim L; get_rows y1 = b; get_rows y2 = b; rsf_layer_inverse L y1 y2 = Ok (x1, x2)\<rbrakk> \<Longrightarrow> get_rows x1 = b \<and> get_cols x1 = dim L \<and> get_rows x2 = b \<and> get_cols x2 = dim L"
  unfolding rsf_layer_inverse_def bind_def assertPair_def assert2DAndLen_def assert_def return_def Let_def rsf_layer_valid_def
  by (auto split: if_splits result.splits list.splits)

lemma rsf_forward_shape: "\<lbrakk>rsf_valid R; \<not> rsf_freed R; tensor_valid x; shape x = [b, 2 * rsf_dim R]; rsf_forward R x = Ok y\<rbrakk> \<Longrightarrow> tensor_valid y \<and> shape y = [b, 2 * rsf_dim R]"
  unfolding rsf_forward_def bind_def assert_def split_def merge_def assert2DAndLen_def return_def Let_def
  by (auto split: if_splits result.splits list.splits)

lemma rsf_inverse_shape: "\<lbrakk>rsf_valid R; \<not> rsf_freed R; tensor_valid y; shape y = [b, 2 * rsf_dim R]; rsf_inverse R y = Ok x\<rbrakk> \<Longrightarrow> tensor_valid x \<and> shape x = [b, 2 * rsf_dim R]"
  unfolding rsf_inverse_def bind_def assert_def split_def merge_def assert2DAndLen_def return_def Let_def
  by (auto split: if_splits result.splits list.splits)

lemma tensor_transpose_twice: "\<lbrakk>tensor_valid t; tensor_transpose t = Ok t'; tensor_transpose t' = Ok t''\<rbrakk> \<Longrightarrow> shape t'' = shape t \<and> data t'' = data t"
  unfolding tensor_transpose_def bind_def assert_def assert2DAndLen_def return_def Let_def get_rows_def get_cols_def tensor_valid_def get_elem_def
  by (auto simp: nth_equalityI split: list.splits if_splits result.splits)

lemma rsf_valid_layers: "rsf_valid R \<Longrightarrow> \<forall>L \<in> set (rsf_layers R). rsf_layer_valid L"
  unfolding rsf_valid_def by simp

lemma rsf_network_length: "rsf_valid R \<Longrightarrow> length (rsf_layers R) = rsf_num_layers R"
  unfolding rsf_valid_def by simp

